const $=s=>document.querySelector(s), names={home:'今日计划',workout:'我的训练',food:'饮食搭配',health:'身体趋势',coach:'AI 教练',plan:'产品方案'};let state={done:[],water:3,goal:'提升力量与线条',minutes:'25',adjusted:false,meal:0};try{Object.assign(state,JSON.parse(localStorage.getItem('forma-demo')||'{}'))}catch{}let page='home';let save=()=>{try{localStorage.setItem('forma-demo',JSON.stringify(state))}catch{}},toast=t=>{$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)},esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function title(k,h,p,button=''){return `<div class="topline"><div><div class="kicker">${k}</div><h1>${h}</h1><div class="muted">${p}</div></div>${button}</div>`}const art=`<svg class="art" viewBox="0 0 260 300" aria-label="伸展身体的抽象插画" role="img"><ellipse cx="145" cy="277" rx="115" ry="22" fill="#d2dac4"/><circle cx="153" cy="118" r="100" fill="#dce4cb"/><path d="M174 135 Q205 179 170 215 L94 266" fill="none" stroke="#384e3d" stroke-width="33" stroke-linecap="round"/><path d="M173 201 L217 261" stroke="#566a46" stroke-width="31" stroke-linecap="round"/><path d="M163 109 Q139 135 173 179" fill="none" stroke="#a7b880" stroke-width="46" stroke-linecap="round"/><path d="M151 120 Q104 87 91 46 M178 121 Q209 77 199 30" fill="none" stroke="#c79572" stroke-width="14" stroke-linecap="round"/><circle cx="162" cy="76" r="24" fill="#c79572"/><path d="M138 77 Q127 44 158 45 Q191 43 187 81 L175 67 Q158 80 138 77" fill="#324638"/><circle cx="182" cy="43" r="15" fill="#324638"/><path d="M40 226 Q10 194 22 162 Q52 179 40 226 M39 230 Q65 191 75 209 Q81 231 39 241" fill="#a4b88c"/></svg>`;
function tasks(){return [['move',state.adjusted?'轻松活动 · 按舒适程度进行':'全身力量 · 基础练习',state.adjusted?'恢复优先 · 不适时停止':`${state.minutes} 分钟 · 徒手 / 弹力带`,'↗'],['meal','好好吃一顿均衡午餐','蔬菜 + 蛋白质 + 主食','◒'],['rest','给自己留一点放松时间','放下屏幕 · 准备休息','☾']].map(([id,t,d,i])=>`<div class="task"><div class="taskicon">${i}</div><div class="taskcontent"><b>${t}</b><p>${d}</p></div><button class="check ${state.done.includes(id)?'done':''}" aria-label="${state.done.includes(id)?'取消完成':'完成'}${t}" onclick="toggle('${id}')">${state.done.includes(id)?'✓':'+'}</button></div>`).join('')}
function toggle(id){state.done=state.done.includes(id)?state.done.filter(x=>x!==id):[...state.done,id];save();render()}
function render(){page=location.hash.slice(1)||'home';if(!names[page])page='home';$('#crumb').textContent=names[page];$('#nav').innerHTML=Object.entries(names).map(([k,v],i)=>`<a href="#${k}" class="${page===k?'active':''}"><span>${['◫','↗','◒','⌁','✳','▤'][i]}</span>${v}</a>`).join('');const v=$('#view');if(page==='home')v.innerHTML=title('WEDNESDAY · 你的第 12 天','嗨，林林。今天，为自己动一动。','循序渐进，身体会记得你的每一份努力。','<button onclick="checkin()">☀ 今日状态反馈</button>')+`<div class="grid"><div><div class="hero"><span class="tag">YOUR PLAN, YOUR PACE</span><h2>让好身材，<br>发生在日常里。</h2><p>当前目标：${esc(state.goal)}。<br>${state.adjusted?'今天降低强度，恢复也是进步。':'今天从一组基础力量练习开始，找到自己的节奏。'}</p><button class="primary" onclick="location.hash='workout'">查看今日训练 &nbsp; ↗</button>${art}</div><div class="stats"><div class="stat">今日行动<strong>${state.done.length}<small> / 3 项</small></strong><span>每一步都值得肯定</span><div class="progress"><i style="width:${state.done.length/3*100}%"></i></div></div><div class="stat">本周训练<strong>${2+(state.done.includes('move')?1:0)}<small> / 3 次</small></strong><span>给力量一点时间</span><div class="progress"><i style="width:${state.done.includes('move')?100:67}%"></i></div></div><div class="stat">饮水记录<strong>${state.water}<small> 杯</small></strong><button style="padding:4px 9px;font-size:10px" onclick="state.water++;save();render()">＋ 记录一杯</button></div></div><div class="card"><div class="cardhead"><h2>今天的小目标</h2><span class="pill">为你安排</span></div>${tasks()}</div></div><div><div class="card ai"><div class="cardhead"><h2>✳ &nbsp;你的 AI 教练</h2><span class="pill">演示建议</span></div><p class="muted" style="font-size:11px">记住你的节奏，照顾你的状态</p><div class="bubble">${state.adjusted?'收到你的疲劳反馈。今天已改为轻松活动，原力量训练暂缓。你可以在训练页恢复原计划。':'昨天完成得很好。今天安排全身基础训练，动作质量比次数更重要。忙碌或疲惫时，我们也可以一起调整。'}</div><button onclick="adapt('time')">今天只有 15 分钟</button> <button onclick="adapt('tired')">今天有点累</button><p><a href="#coach">和教练聊聊 &nbsp; ↗</a></p></div><div class="card section"><div class="cardhead"><h2>本周节奏</h2><span class="muted">示例 · 第 2 周</span></div><div class="week">${['一','二','三','四','五','六','日'].map((x,i)=>`<div class="day ${i<2?'done':i===2?'today':''}">${x}<br>${i<2?'✓':i===2?'●':'·'}</div>`).join('')}</div><p class="note">力量、活动与休息交替安排。<br>留出恢复时间，也是计划的一部分。</p></div><div class="card section" style="background:#eee9df"><span class="kicker">A LITTLE REMINDER</span><h3>体重之外，也有很多进步。</h3><p class="note">多完成一次动作，走路更轻松，精神更好——都值得被看见。</p><a href="#health">看看我的变化 ↗</a></div></div></div>`;
if(page==='workout')v.innerHTML=title('MOVE WITH INTENTION','把力量，练进生活里。','今天的计划，配合今天的你。')+`<div class="banner">${state.adjusted?'已根据疲劳反馈调整：今天优先恢复。':'示例训练适用于已完成健康筛查的成年初学者；强度以个人能力为准。'}</div><div class="grid"><div class="card"><span class="pill">${state.adjusted?'恢复日':'全身力量 · 初学者'}</span><h2 style="margin-top:20px">${state.adjusted?'轻松活动与舒适伸展':state.minutes+' 分钟基础训练'}</h2>${(state.adjusted?['舒适步行｜自主选择时长','温和活动肩颈｜避免疼痛范围','放松呼吸｜结束后记录感受']:['热身活动｜5 分钟','椅子坐站｜1–2 组 × 8 次','墙面俯卧撑｜1–2 组 × 8 次','站姿弹力带划船｜1–2 组 × 8 次','舒缓整理｜3 分钟']).map((x,i)=>`<div class="task"><div class="taskicon">0${i+1}</div><div>${x}</div></div>`).join('')}<p class="note">组间充分休息，保留余力。出现疼痛、胸痛、明显头晕等不适，停止训练并寻求适当医疗帮助。15 分钟版各动作仅做一组。</p><div class="row"><button class="primary" onclick="workoutDone()">${state.done.includes('move')?'已完成 · 更新反馈':'记录完成与感受'}</button><button onclick="adapt('time')">改为 15 分钟</button><button onclick="state.adjusted=false;state.minutes='25';save();render()">恢复原计划</button></div></div><div class="card ai"><h2>为什么这样安排？</h2><p>目标：${esc(state.goal)}</p><p>通过全身基础动作建立力量与运动习惯，再根据完成情况逐步进阶。</p><p>本示例以每周三次力量训练为安排方向，休息日穿插轻松活动。正式版会根据评估结果生成个人计划。</p><button onclick="checkin()">反馈今天的状态 ↗</button></div></div>`;
if(page==='food'){const meals=state.meal%2?['燕麦 + 鸡蛋 + 水果','豆腐杂粮饭 + 时蔬','鸡肉菌菇面 + 青菜']:['全麦面包 + 牛奶 + 水果','鸡肉糙米碗 + 时蔬','清蒸鱼 + 米饭 + 绿叶菜'];v.innerHTML=title('NOURISH, DON’T PUNISH','好好吃饭，也是塑形的一部分。','不追求每餐完美，找到可以长期坚持的搭配。','<button onclick="state.meal++;save();render()">↻ 换一套搭配</button>')+`<div class="cards3">${meals.map((m,i)=>`<div class="card"><div class="food">${['🥣','🥗','🍲'][i]}</div><p class="kicker">${['BREAKFAST','LUNCH','DINNER'][i]}</p><h3>${m}</h3><p class="note">示例组合 · 份量按饥饿感、活动量和个人需求调整。替换时注意过敏原。</p><button onclick="mealLog('${m}')">记录这餐</button></div>`).join('')}</div><div class="grid section"><div class="card"><h2>外卖也能好好搭配</h2><p>优先找到主食、蛋白质来源和蔬菜。今天吃多了一点，也不用通过跳餐或额外运动补偿。</p><button onclick="location.hash='coach'">让教练帮我选 ↗</button></div><div class="card ai"><h2>你的饮食偏好</h2><p>正式版会考虑过敏、忌口、预算、烹饪条件和外卖习惯。</p><p class="note">Demo 不计算个人热量缺口，也不通过照片推断精确营养。</p></div></div>`}
if(page==='health')v.innerHTML=title('MORE THAN A NUMBER','看见每一种进步。','以下趋势均为虚构样例，不代表使用效果。','<button onclick="measure()">＋ 添加记录</button>')+`<div class="grid"><div class="card"><div class="cardhead"><h2>腰围趋势</h2><span class="pill">近 4 周 · 示例</span></div><span class="big">${state.waist||'72.5'}</span> cm <span class="muted">${state.waist?'· 你的本地记录':'· 最近一次示例测量'}</span><svg class="chart" viewBox="0 0 600 190" role="img" aria-label="示例腰围四周趋势：74、73.6、73.8、72.5厘米"><path d="M40 40H570M40 95H570M40 150H570" stroke="#e5eadf"/><path d="M40 60L210 83L390 72L570 140" stroke="#8ca769" stroke-width="3" fill="none"/><g fill="#8ca769"><circle cx="40" cy="60" r="5"/><circle cx="210" cy="83" r="5"/><circle cx="390" cy="72" r="5"/><circle cx="570" cy="140" r="5"/></g><g fill="#8a9385" font-size="12"><text x="30" y="180">第 1 周</text><text x="190" y="180">第 2 周</text><text x="370" y="180">第 3 周</text><text x="530" y="180">第 4 周</text></g></svg><p class="note">曲线固定为示例；新记录仅更新上方数值。围度受测量方法和短期波动影响，建议在相近条件下观察长期趋势。</p></div><div class="healthgrid"><div class="card"><span class="muted">本周平均睡眠 · 示例</span><p class="big">7.2 <small>h</small></p><span class="pill">规律比单日数字重要</span></div><div class="card"><span class="muted">训练感受 · 示例</span><p style="font-size:26px">更有力量</p><p class="note">同样的动作，完成更从容</p></div><div class="card" style="grid-column:1/-1"><h3>健康记录，由你决定</h3><p class="note">周期、睡眠、疼痛和围度均为可选记录。Demo 未连接设备，不进行疾病诊断。</p><button onclick="if(confirm('清除本浏览器的 Demo 记录？')){localStorage.removeItem('forma-demo');location.reload()}">清除本地记录</button></div></div></div>`;
if(page==='coach')v.innerHTML=title('YOUR AI COMPANION','计划可以变，陪伴一直在。','告诉我今天的实际情况，我们一起找到能做到的那一步。')+`<div class="banner">交互演示：使用本地预设规则回复，未连接大模型。请勿输入真实敏感健康信息。</div><div class="card"><div class="chatlog" id="chatlog"><div class="message">你好，林林。我是你的塑形教练。今天想调整训练，还是需要饮食搭配的灵感？<br>你可以试试：“今天只有15分钟”或“今天很累”。</div></div><div class="row"><button onclick="chat('今天只有15分钟')">只有 15 分钟</button><button onclick="chat('今天很累')">今天很累</button><button onclick="chat('中午吃外卖怎么选')">外卖怎么选</button></div><form class="chatform" onsubmit="event.preventDefault();chat(this.q.value);this.reset()"><input name="q" required maxlength="400" placeholder="说说今天的状态…" aria-label="发给教练的消息"><button class="primary">发送 ↗</button></form></div>`;
if(page==='plan')fetch('plan.html').then(r=>r.text()).then(t=>{if(page==='plan')v.innerHTML=t});}
function show(html){$('#modal').innerHTML=html;$('#modal').showModal()}function closeModal(){$('#modal').close()}function onboard(){show(`<h2>先找到属于你的目标</h2><p class="note">Demo 仅保存目标与时间偏好到当前浏览器。</p><form onsubmit="event.preventDefault();state.goal=this.goal.value;state.minutes=this.minutes.value;save();closeModal();render();toast('目标已更新')"><label>现阶段最想改善什么？<select name="goal">${['提升力量与线条','建立规律运动习惯','改善体能与精神状态'].map(x=>`<option ${x===state.goal?'selected':''}>${x}</option>`).join('')}</select></label><label>每次可用的时间<select name="minutes"><option value="15">15 分钟</option><option value="25" ${state.minutes==='25'?'selected':''}>25 分钟</option><option value="35" ${state.minutes==='35'?'selected':''}>35 分钟</option></select></label><button class="primary">保存目标</button> <button type="button" onclick="closeModal()">取消</button></form>`)}
function checkin(){show('<h2>今天的身体感觉怎么样？</h2><p>计划应该适应你今天的状态。</p><div class="row"><button onclick="closeModal();toast(\'已记录：状态不错，保留当前计划\')">☀ 状态不错</button><button onclick="closeModal();adapt(\'tired\')">☁ 有些疲惫</button><button onclick="closeModal();adapt(\'pain\')">身体疼痛 / 不适</button></div><p class="note">这是体验流程；正式版需进一步询问症状和训练限制。</p><button onclick="closeModal()">关闭</button>')}
function adapt(type){if(type==='pain'){show('<h2>先暂停训练</h2><p>疼痛或不适需要先明确原因，今天不要勉强完成计划。若出现胸痛、晕厥或严重呼吸困难，请及时寻求当地紧急医疗帮助。</p><button onclick="closeModal()">知道了</button>');return}show(`<h2>建议调整今天的计划</h2><p>${type==='time'?'将训练缩短为 15 分钟，保留热身、基础动作和整理，每个动作做一组。':'把今天的力量训练改为舒适范围内的轻松活动，恢复后再安排训练。'}</p><p class="note">确认后会同步更新今日计划和训练页。</p><button class="primary" onclick="applyAdapt('${type}')">应用调整</button> <button onclick="closeModal()">保留原计划</button>`)}function applyAdapt(t){if(t==='time')state.minutes='15';else state.adjusted=true;save();closeModal();if(page!=='coach')render();toast('今日计划已同步更新')}
function workoutDone(){show('<h2>练完感觉如何？</h2><p>用感受帮助下一次计划更适合你。</p><div class="row">'+['轻松','刚刚好','有些吃力'].map(x=>`<button onclick="if(!state.done.includes('move'))state.done.push('move');state.effort='${x}';save();closeModal();render();toast('已记录训练与感受：${x}')">${x}</button>`).join('')+'</div><p class="note">如果出现疼痛，请暂停并寻求专业评估。</p><button onclick="closeModal()">取消</button>')}
function mealLog(m){if(!state.done.includes('meal'))state.done.push('meal');save();toast('已记录：'+m)}function measure(){show('<h2>记录一次腰围</h2><form onsubmit="event.preventDefault();state.waist=Number(this.waist.value).toFixed(1);save();closeModal();render();toast(\'已保存到当前浏览器\')"><label>腰围（cm）<input name="waist" type="number" step="0.1" min="30" max="250" required></label><button class="primary">保存记录</button> <button type="button" onclick="closeModal()">取消</button></form>')}
function chat(q){q=q.trim();if(!q)return;const log=$('#chatlog');let msg=document.createElement('div');msg.className='message user';msg.textContent=q;log.append(msg);let answer='这是预设交互 Demo，暂时只能演示时间不足、疲劳、外卖和身体不适场景。正式版会结合个人评估、历史反馈与审核过的知识库回答。';let action='';if(/疼|痛|头晕|胸闷/.test(q))answer='先暂停训练，不要带着不适坚持。持续或明显的不适请向专业人员咨询；胸痛、晕厥或严重呼吸困难应及时寻求当地紧急医疗帮助。';else if(/15|时间|忙/.test(q)){answer='可以把今天的训练改成 15 分钟。保留热身和基础动作，减少组数。要应用到今日计划吗？';action='time'}else if(/累|疲|没睡/.test(q)){answer='今天先照顾恢复。建议把力量训练改成舒适范围内的轻松活动，不需要补练。要应用这个调整吗？';action='tired'}else if(/吃|餐|外卖/.test(q))answer='可以选包含主食、蛋白质来源和蔬菜的组合，例如米饭搭配鸡肉或豆腐与时蔬。按饥饿感和需求调整份量，注意过敏原；不必因为一顿外卖而跳过下一餐。';let reply=document.createElement('div');reply.className='message';reply.textContent=answer;if(action){let b=document.createElement('button');b.textContent='查看并确认调整';b.onclick=()=>adapt(action);reply.append(document.createElement('br'),b)}log.append(reply);log.scrollTop=log.scrollHeight}
window.addEventListener('hashchange',()=>render());render();
